/**
 * Forward-only, numbered SQL migration runner.
 *
 * Chosen over an ORM's autogenerated migrations on purpose: the correctness of
 * this system rests on explicit constraints (partial unique indexes, ON CONFLICT
 * arbiters, CHECK guards). Those must be readable and reviewable, not generated.
 *
 * Each migration runs in its own transaction and is recorded with a checksum, so
 * an edited historical migration is detected instead of silently diverging.
 */
import { createHash } from 'node:crypto';
import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Db } from './driver.js';

const here = path.dirname(fileURLToPath(import.meta.url));
export const DEFAULT_MIGRATIONS_DIR = path.resolve(here, '../migrations');

export interface MigrationRecord {
  name: string;
  checksum: string;
  appliedAt: string;
}

export class MigrationChecksumError extends Error {
  constructor(name: string) {
    super(
      `Migration "${name}" has changed since it was applied. ` +
        `Migrations are forward-only: add a new numbered migration instead of editing history.`,
    );
    this.name = 'MigrationChecksumError';
  }
}

const checksum = (sql: string) => createHash('sha256').update(sql).digest('hex');

async function ensureLedger(db: Db): Promise<void> {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      name       text PRIMARY KEY,
      checksum   text NOT NULL,
      applied_at timestamptz NOT NULL DEFAULT now()
    );
  `);
}

export async function appliedMigrations(db: Db): Promise<MigrationRecord[]> {
  await ensureLedger(db);
  const r = await db.query<{ name: string; checksum: string; applied_at: Date | string }>(
    `SELECT name, checksum, applied_at FROM schema_migrations ORDER BY name`,
  );
  return r.rows.map((row) => ({
    name: row.name,
    checksum: row.checksum,
    appliedAt: new Date(row.applied_at).toISOString(),
  }));
}

/**
 * Applies every pending migration in filename order.
 * Idempotent: re-running with no changes is a no-op.
 */
export async function runMigrations(
  db: Db,
  dir: string = DEFAULT_MIGRATIONS_DIR,
): Promise<{ applied: string[]; skipped: string[] }> {
  await ensureLedger(db);

  const files = (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort();
  if (files.length === 0) throw new Error(`No .sql migrations found in ${dir}`);

  const done = new Map((await appliedMigrations(db)).map((m) => [m.name, m.checksum]));
  const applied: string[] = [];
  const skipped: string[] = [];

  for (const file of files) {
    const sql = await readFile(path.join(dir, file), 'utf8');
    const sum = checksum(sql);

    const previous = done.get(file);
    if (previous !== undefined) {
      if (previous !== sum) throw new MigrationChecksumError(file);
      skipped.push(file);
      continue;
    }

    await db.withTransaction(async (tx) => {
      // Multi-statement DDL cannot be parameterised; the files are repo-controlled, not user input.
      await tx.exec(sql);
      await tx.query(`INSERT INTO schema_migrations (name, checksum) VALUES ($1, $2)`, [file, sum]);
    });
    applied.push(file);
  }

  return { applied, skipped };
}
